export const PIECE_BY_ID: ReadonlyMap<string, Piece> = new Map(
  STARTER_PIECES.map((piece) => [piece.id, piece]),
);

export function piece(id: string): Piece {
  const found = PIECE_BY_ID.get(id);
  if (found === undefined) throw new Error(`Unknown fixture piece ${id}`);
  return found;
}

export function makePiece(overrides: Partial<Piece> & { id: string }): Piece {
  return {
    name: overrides.id,
    category: "top",
    colour: "white",
    era: "now",
    formality: 2,
    warmth: 1,
    price: 10,
    features: [],
    ...overrides,
  };
}
